std::vector<unsigned char> data(size);
for (int i = 0; i < size; i++) {
    data[i] = 0;
}
leveldb::BloomFilterPolicy policy;
for (int i = 0; i < n; i++) {
    uint32_t hash = policy.Hash(keys[i]);
    for (size_t j = 0; j < bits_per_key; j++) {
        size_t index = (hash % (size * 8)) / 8;
        size_t bit_pos = (hash % (size * 8)) % 8;
        data[index] |= (1 << bit_pos);
        hash += 0x9e3779b9 + (hash << 6) + (hash >> 2);
    }
}
dst->assign(reinterpret_cast<const char*>(data.data()), data.size());

